#!/usr/bin/env python3
"""Checks the m68k assembly generated by gcc (-S, Motorola syntax): every function that writes a register
the caller expects to be preserved (d2-d7, a2-a6) must have pushed it in its prologue.

Safeguard against a bug in m68k-amigaos-gcc 16.1.1b (fixed in 16.2): a register picked by reload was used
without being saved, which corrupted the caller's registers.

Usage: check-saves.py file.s [...]   -> exit code 1 if a function is at fault.
"""
import re
import sys

CALLEE_SAVED = {f"d{i}" for i in range(2, 8)} | {f"a{i}" for i in range(2, 7)}
REG = r"(?:[ad][0-7]|sp|fp)"
NO_WRITE = {"cmp", "cmpa", "cmpi", "cmpm", "tst", "btst", "pea", "jsr", "jmp", "bsr", "rts", "chk", "link", "unlk"}


def reglist(text):
    """'d2/a2/a5-a6' or '#8230' (mask of a movem to -(sp)) -> {'d2', 'a2', 'a5', 'a6'}"""
    regs = set()
    if text.startswith("#"):
        # In predecrement mode, bit 15 means d0 and bit 0 means a7.
        mask = int(text[1:], 0)
        names = [f"d{i}" for i in range(8)] + [f"a{i}" for i in range(8)]
        return {names[15 - bit] for bit in range(16) if mask & (1 << bit)}
    for part in text.split("/"):
        m = re.fullmatch(r"([ad])([0-7])-([ad])([0-7])", part)
        if m:
            regs |= {f"{m.group(1)}{i}" for i in range(int(m.group(2)), int(m.group(4)) + 1)}
        else:
            regs.add(part)
    return regs


def split_operands(ops):
    """Splits on commas outside parentheses."""
    out, depth, cur = [], 0, ""
    for c in ops:
        if c in "([":
            depth += 1
        elif c in ")]":
            depth -= 1
        if c == "," and depth == 0:
            out.append(cur)
            cur = ""
        else:
            cur += c
    out.append(cur)
    return [o.strip() for o in out if o.strip()]


def check(path):
    bad = 0
    funcs = []  # (name, line number, [instructions])
    for num, line in enumerate(open(path, encoding="latin-1"), 1):
        line = line.split("|")[0].rstrip()
        m = re.match(r"^([A-Za-z_.$][\w.$]*):", line)
        # Only C symbols (prefixed with _ on m68k-amigaos) start a function; gcc's internal labels
        # (L12, LC0, and with -g LM8, LCFI1, LVL15...) stay in the current function.
        if m and m.group(1).startswith("_"):
            funcs.append((m.group(1), num, []))
        elif funcs and line.startswith(("\t", " ")) and not line.strip().startswith("."):
            funcs[-1][2].append(line.strip())

    for name, num, insns in funcs:
        saved, written = set(), set()
        for ins in insns:
            parts = ins.split(None, 1)
            op = parts[0].split(".")[0]
            ops = split_operands(parts[1]) if len(parts) > 1 else []
            if op == "movem":
                if ops[-1] == "-(sp)":
                    saved |= reglist(ops[0])
                continue  # restore: movem (sp)+,list
            if op in NO_WRITE or not ops:
                continue
            if op == "move" and ops[-1] == "-(sp)" and ops[0] in CALLEE_SAVED:
                saved.add(ops[0])
                continue
            if ops[0] == "(sp)+":
                continue  # restore: move.l (sp)+,reg
            dests = ops if op == "exg" else [ops[-1]]
            for dest in dests:
                for d in dest.split(":"):  # 68020+ register pairs: divsl.l / mulu.l ...,d2:d3
                    if re.fullmatch(REG, d) and d in CALLEE_SAVED:
                        written.add(d)
        missing = written - saved
        if missing:
            bad += 1
            # gcc format (file:line: error:) for VS Code's problemMatcher
            print(f"{path}:{num}: error: {name} modifies {', '.join(sorted(missing))} without saving it "
                  f"(compiler code generation bug)")
    return bad


if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    sys.exit(1 if sum(check(p) for p in sys.argv[1:]) else 0)
